mapper.update:
UPDATE REP_FEE_TRD as A, ( select BUSI_ID, FEE_ID, PROD_ID, PAID_FEE, PAY_DATE, INPUT_TYPE, INPUT_USER, STATUS, ADAPTER_ID, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, CASH_TYPE2 from ( select TEMP.* from (
SELECT #{item.busiId,jdbcType=VARCHAR} as BUSI_ID, #{item.feeId,jdbcType=VARCHAR} as FEE_ID, #{item.prodId,jdbcType=VARCHAR} as PROD_ID, #{item.paidFee,jdbcType=DECIMAL} as PAID_FEE, #{item.payDate,jdbcType=DATE} as PAY_DATE , #{item.inputType,jdbcType=VARCHAR} as INPUT_TYPE, #{item.inputUser,jdbcType=VARCHAR} as INPUT_USER, #{item.status,jdbcType=VARCHAR} as STATUS, #{item.adapterId,jdbcType=VARCHAR} as ADAPTER_ID, #{item.createUser,jdbcType=VARCHAR} as CREATE_USER, #{item.createDept,jdbcType=VARCHAR} as CREATE_DEPT , #{item.createTime,jdbcType=TIMESTAMP} as CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} as UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} as UPDATE_TIME, #{item.cashType2,jdbcType=VARCHAR} as CASH_TYPE2 FROM dual
) TEMP ) de ) AS B set A.FEE_ID=B.FEE_ID, A.PROD_ID=B.PROD_ID, A.PAID_FEE=B.PAID_FEE, A.PAY_DATE=B.PAY_DATE, A.INPUT_TYPE=B.INPUT_TYPE, A.INPUT_USER=B.INPUT_USER, A.STATUS=B.STATUS, A.ADAPTER_ID=B.ADAPTER_ID, A.CREATE_USER=B.CREATE_USER, A.CREATE_DEPT=B.CREATE_DEPT, A.CREATE_TIME=B.CREATE_TIME, A.UPDATE_USER=B.UPDATE_USER, A.UPDATE_TIME=B.UPDATE_TIME, A.CASH_TYPE2=B.CASH_TYPE2 where A.BUSI_ID = B.BUSI_ID; insert into REP_FEE_TRD(BUSI_ID, FEE_ID, PROD_ID, PAID_FEE, PAY_DATE, INPUT_TYPE, INPUT_USER, STATUS, ADAPTER_ID, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, CASH_TYPE2) select BUSI_ID, FEE_ID, PROD_ID, PAID_FEE, PAY_DATE, INPUT_TYPE, INPUT_USER, STATUS, ADAPTER_ID, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, CASH_TYPE2 from ( select TEMP.* from (
SELECT #{item.busiId,jdbcType=VARCHAR} as BUSI_ID, #{item.feeId,jdbcType=VARCHAR} as FEE_ID, #{item.prodId,jdbcType=VARCHAR} as PROD_ID, #{item.paidFee,jdbcType=DECIMAL} as PAID_FEE, #{item.payDate,jdbcType=DATE} as PAY_DATE , #{item.inputType,jdbcType=VARCHAR} as INPUT_TYPE, #{item.inputUser,jdbcType=VARCHAR} as INPUT_USER, #{item.status,jdbcType=VARCHAR} as STATUS, #{item.adapterId,jdbcType=VARCHAR} as ADAPTER_ID, #{item.createUser,jdbcType=VARCHAR} as CREATE_USER, #{item.createDept,jdbcType=VARCHAR} as CREATE_DEPT , #{item.createTime,jdbcType=TIMESTAMP} as CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} as UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} as UPDATE_TIME, #{item.cashType2,jdbcType=VARCHAR} as CASH_TYPE2 FROM dual
) TEMP where not exists (select 1 from REP_FEE_TRD CII where CII.BUSI_ID = TEMP.BUSI_ID) ) de ;

